"""Bundle the static catalogue + SQLite schema into web/data.js for the browser build.

    python tools/build_web.py
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def main():
    data = json.loads((ROOT / "data" / "gamedata.json").read_text())
    schema = (ROOT / "data" / "schema.sql").read_text()
    out = ROOT / "web" / "data.js"
    out.write_text(
        "/* AUTO-GENERATED by tools/build_web.py - do not edit. */\n"
        f"window.EXODEX_DATA = {json.dumps(data, separators=(',', ':'))};\n"
        f"window.EXODEX_SCHEMA = {json.dumps(schema)};\n"
    )
    print(f"wrote {out.relative_to(ROOT)} ({out.stat().st_size // 1024} KB)")


if __name__ == "__main__":
    main()
